//! QA-01.1: minimal, hand-written compatibility samples.
//!
//! The fixture in `tests/fixtures/qa01/` is generated by
//! `scripts/qa01_min_samples.py`.  It deliberately contains an error formula
//! (`1/0`), a string-producing formula with Chinese text, and a boolean
//! formula so a loader/recalculator cannot silently treat all formulas as
//! numbers or drop inline strings.

use std::path::{Path, PathBuf};

use sheetcore::formula::{self, ErrKind};
use sheetcore::model::Value;

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/qa01")
        .join(name)
}

fn out_path(name: &str) -> PathBuf {
    std::env::current_exe()
        .expect("test executable path")
        .parent()
        .expect("test executable directory")
        .join(format!("qa01_{}_{}.xlsx", name, std::process::id()))
}

#[test]
fn formula_min_fixture_loads_recalculates_and_keeps_formulas() {
    let mut wb = sheetcore::xlsx::load(&fixture("qa01_formula_min.xlsx")).expect("load formula sample");
    formula::recalc_all(&mut wb);
    let sh = wb.sheet(0);

    assert_eq!(sh.get(0, 0).unwrap().value, Value::Number(1.0));
    assert_eq!(sh.get(1, 0).unwrap().value, Value::Number(2.0));
    assert_eq!(sh.get(2, 0).unwrap().value, Value::Number(3.0));
    assert_eq!(sh.get(0, 2).unwrap().value, Value::Text("财务".into()));
    assert_eq!(sh.get(1, 2).unwrap().value, Value::Text("财务".into()));
    assert!(matches!(sh.get(0, 1).unwrap().value, Value::Error(ErrKind::Div0)));
    assert_eq!(sh.get(1, 1).unwrap().value, Value::Text("ok".into()));
    assert_eq!(sh.get(2, 1).unwrap().value, Value::Number(3.0));
    assert_eq!(sh.get(0, 3).unwrap().value, Value::Bool(true));
    assert_eq!(sh.get(3, 0).unwrap().value, Value::Number(1.0));

    let formulas: Vec<&str> = [
        (2, 0, "=SUM(A1:A2)"),
        (0, 1, "=1/0"),
        (1, 1, "=IFERROR(B1,\"ok\")"),
        (1, 2, "=CONCATENATE(\"财\",\"务\")"),
        (0, 3, "=A1=1"),
    ]
    .iter()
    .map(|(r, c, expected)| {
        let actual = sh.formula_of(*r, *c).expect("formula text");
        assert_eq!(actual, *expected);
        actual
    })
    .collect();
    assert_eq!(formulas.len(), 5);

    let out = out_path("formula");
    let _ = std::fs::remove_file(&out);
    sheetcore::xlsx::save(&out, &wb).expect("save formula sample");
    let mut back = sheetcore::xlsx::load(&out).expect("reload formula sample");
    formula::recalc_all(&mut back);
    let sh = back.sheet(0);
    assert!(matches!(sh.get(0, 1).unwrap().value, Value::Error(ErrKind::Div0)));
    assert_eq!(sh.get(1, 1).unwrap().value, Value::Text("ok".into()));
    assert_eq!(sh.get(1, 2).unwrap().value, Value::Text("财务".into()));
    assert_eq!(sh.get(2, 0).unwrap().value, Value::Number(3.0));
    let _ = std::fs::remove_file(out);
}

#[test]
fn edit_min_fixture_keeps_existing_cells_and_inline_text() {
    let wb = sheetcore::xlsx::load(&fixture("qa01_edit_min.xlsx")).expect("load edit sample");
    let sh = wb.sheet(0);
    assert_eq!(sh.get(0, 0).unwrap().value, Value::Text("old".into()));
    assert_eq!(sh.get(0, 1).unwrap().value, Value::Text("second".into()));
    assert_eq!(sh.get(1, 0).unwrap().value, Value::Text("existing".into()));
}
